const starter = {
  title: 'The Last Train',
  scenes: [
    {id:'s1',name:'Platform at midnight',bg:'station',speaker:'Mira',text:'The last train always sounds lonelier in the rain.',next:'s2'},
    {id:'s2',name:'A familiar face',bg:'station',speaker:'Ren',text:'You still wait for it, even when you know it won’t come.',choices:[{text:'Ask him what he means',target:'s3'},{text:'Let the silence answer',target:'s4'}]},
    {id:'s3',name:'The thing unsaid',bg:'cafe',speaker:'Mira',text:'Then tell me. What are you really waiting for?',next:'s4'},
    {id:'s4',name:'First light',bg:'garden',speaker:'Ren',text:'Maybe just one more minute with you.',next:null}
  ]
};
let project = loadProject(); let selectedId=project.scenes[0].id; let playing=false; let zoom=100; let history=[]; let future=[]; let toastTimer;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
function loadProject(){try{const p=JSON.parse(localStorage.getItem('fable-project'));if(p&&Array.isArray(p.scenes)&&p.scenes.length)return p}catch(e){}return structuredClone(starter)}
function persist(){localStorage.setItem('fable-project',JSON.stringify(project));$('#saveState').textContent='All changes saved';$('.saved-dot').style.background='#79b397'}
function changed(){history.push(JSON.stringify(project));if(history.length>30)history.shift();future=[];$('#saveState').textContent='Saving…';$('.saved-dot').style.background='#e2b45a';render();clearTimeout(window.saveTimeout);window.saveTimeout=setTimeout(persist,350)}
function selected(){return project.scenes.find(s=>s.id===selectedId)||project.scenes[0]}
function showToast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2300)}
function render(){if(!project.scenes.length){project.scenes.push({...starter.scenes[0],id:makeId()});selectedId=project.scenes[0].id}if(!project.scenes.some(s=>s.id===selectedId))selectedId=project.scenes[0].id;
  $('#projectTitle').textContent=project.title;$('#sideTitle').textContent=project.title;$('#sceneTotal').textContent=`${project.scenes.length} SCENES`;$('#chapterCount').textContent=project.scenes.length;$('#inspectorTitle').textContent=`Scene ${String(project.scenes.indexOf(selected())+1).padStart(2,'0')}`;
  $('#sceneList').innerHTML=project.scenes.map((s,i)=>`<button class="scene-item ${s.id===selectedId?'active':''}" data-id="${s.id}"><span class="scene-number">${String(i+1).padStart(2,'0')}</span><span class="scene-item-copy"><strong>${esc(s.name||'Untitled scene')}</strong><small>${esc(s.speaker||'Narrator')} · ${s.choices?.length||0?`${s.choices.length} choices`:'Dialogue'}</small></span><span class="scene-glyph">${s.choices?.length?'⑂':'◦'}</span></button>`).join('');
  $$('.scene-item').forEach(b=>b.onclick=()=>{selectedId=b.dataset.id;playing=false;setMode(false);render()});
  const s=selected();$('#sceneName').value=s.name||'';$('#dialogueInput').value=s.text||'';$('#speakerSelect').value=['Mira','Ren','Narrator'].includes(s.speaker)?s.speaker:'Mira';$('#charCountText').textContent=`${(s.text||'').length} / 220`;$('#bgName').textContent=({station:'Rainy station',cafe:'Little café',garden:'Moon garden'})[s.bg]||'Rainy station';$('#sceneBg').className=`scene-bg bg-${s.bg||'station'}`;$('#fieldLineNumber').textContent=String(project.scenes.indexOf(s)+1).padStart(2,'0');$('#speakerTag').textContent=(s.speaker||'Narrator').toUpperCase();$('#dialogueText').textContent=s.text||'';$('#lineNumber').innerHTML=`${String(project.scenes.indexOf(s)+1).padStart(2,'0')} <i>/</i> ${String(project.scenes.length).padStart(2,'0')}`;
  $('#charLeft').style.display=s.speaker==='Ren'?'none':'';$('#charRight').style.display=s.speaker==='Mira'||s.speaker==='Narrator'?'':'none';$('#choicesConfig').innerHTML=(s.choices||[]).map((c,i)=>`<div class="choice-edit"><input data-choice="${i}" value="${escAttr(c.text)}" aria-label="Choice ${i+1}"><button class="remove-choice" data-remove="${i}" title="Remove choice">×</button></div>`).join('');
  $$('[data-choice]').forEach(inp=>inp.oninput=()=>{s.choices[+inp.dataset.choice].text=inp.value;$('#dialogueText').textContent=s.text;changed()});$$('[data-remove]').forEach(btn=>btn.onclick=()=>{s.choices.splice(+btn.dataset.remove,1);if(!s.choices.length)delete s.choices;changed()});
  $('#choiceOverlay').classList.remove('visible');$('#choiceOverlay').innerHTML='';$('#continueHint').textContent=playing?(s.choices?.length?'MAKE A CHOICE':'CLICK TO CONTINUE'):'CLICK TO CONTINUE';$('#previewStatus').textContent=playing?'Playing preview':'Preview ready';
}
function makeId(){return 's'+Math.random().toString(36).slice(2,8)}function esc(x=''){return String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function escAttr(x=''){return esc(x)}
function setMode(play){playing=play;$('#playMode').classList.toggle('active',play);$('#editMode').classList.toggle('active',!play);$('#previewStatus').textContent=play?'Playing preview':'Preview ready';if(play){$('#continueHint').textContent=selected().choices?.length?'MAKE A CHOICE':'CLICK TO CONTINUE';showToast('Preview started · Click the scene to advance')}else{$('#choiceOverlay').classList.remove('visible');$('#choiceOverlay').innerHTML=''}}
function advance(target){let s=selected();let id=target||s.next;if(!id){setMode(false);showToast('The end · Your story is ready to remix');return}if(!project.scenes.some(x=>x.id===id)){setMode(false);showToast('End of this story path');return}selectedId=id;render()}
$('#editMode').onclick=()=>setMode(false);$('#playMode').onclick=()=>setMode(true);$('#vnScreen').onclick=e=>{if(!playing)return;const s=selected();if(s.choices?.length){if(!e.target.closest('.choice-button'))showToast('Choose a path to continue');return}advance()};
function renderChoices(){const s=selected(),box=$('#choiceOverlay');box.innerHTML=(s.choices||[]).map((c,i)=>`<button class="choice-button" data-target="${escAttr(c.target||'')}" aria-label="Choice ${i+1}">${esc(c.text)}</button>`).join('');box.classList.toggle('visible',playing&&!!s.choices?.length);$$('.choice-button').forEach(b=>b.onclick=e=>{e.stopPropagation();advance(b.dataset.target)})}
const renderBase=render;render=function(){renderBase();renderChoices()};
$('#sceneName').oninput=e=>{selected().name=e.target.value;changed()};$('#dialogueInput').oninput=e=>{selected().text=e.target.value;$('#charCountText').textContent=`${e.target.value.length} / 220`;$('#dialogueText').textContent=e.target.value;changed()};$('#speakerSelect').onchange=e=>{selected().speaker=e.target.value;changed()};
$('#bgChoice').onclick=()=>$('#bgOptions').classList.toggle('open');$('#browseBg').onclick=()=>$('#bgOptions').classList.toggle('open');$$('[data-bg]').forEach(b=>b.onclick=()=>{selected().bg=b.dataset.bg;$('#bgOptions').classList.remove('open');changed()});document.addEventListener('click',e=>{if(!e.target.closest('#bgChoice')&&!e.target.closest('#bgOptions')&&!e.target.closest('#browseBg'))$('#bgOptions').classList.remove('open')});
function addScene(){const id=makeId();const scene={id,name:'A new moment',bg:'station',speaker:'Narrator',text:'Write your next line here…',next:null};let idx=project.scenes.findIndex(s=>s.id===selectedId);project.scenes.splice(idx+1,0,scene);if(project.scenes[idx])project.scenes[idx].next=id;selectedId=id;setMode(false);changed();showToast('New scene added')}
$('#addScene').onclick=addScene;$('#addSceneTop').onclick=addScene;$('#duplicateScene').onclick=()=>{const copy=structuredClone(selected());copy.id=makeId();copy.name=(copy.name||'Scene')+' copy';const i=project.scenes.findIndex(s=>s.id===selectedId);project.scenes.splice(i+1,0,copy);selectedId=copy.id;changed();showToast('Scene duplicated')};$('#deleteScene').onclick=()=>{if(project.scenes.length<=1){showToast('Your story needs at least one scene');return}const i=project.scenes.findIndex(s=>s.id===selectedId),next=project.scenes[i+1]||project.scenes[i-1];project.scenes.splice(i,1);project.scenes.forEach(s=>{if(s.next===selectedId)s.next=next.id;if(s.choices)s.choices.forEach(c=>{if(c.target===selectedId)c.target=next.id})});selectedId=next.id;changed();showToast('Scene deleted')};
$('#addChoice').onclick=()=>{const s=selected();if(!s.choices)s.choices=[];const target=project.scenes.find(x=>x.id!==s.id)?.id||'';s.choices.push({text:`Choice ${s.choices.length+1}`,target});changed();showToast('Choice added to this scene')};
$('#addCharacter').onclick=()=>{let s=selected();s.speaker='Narrator';$('#speakerSelect').value='Narrator';changed();showToast('Narrator added · Add a name in the speaker menu')};$$('.char-toggle').forEach(b=>b.onclick=()=>{const el=$('#'+b.dataset.target);el.style.opacity=el.style.opacity==='0.25'?'1':'0.25';showToast(el.style.opacity==='1'?'Character visible':'Character hidden in preview')});
$('#zoomIn').onclick=()=>{zoom=Math.min(120,zoom+10);$('#vnScreen').style.transform=`scale(${zoom/100})`;$('#zoomLabel').textContent=`${zoom}%`};$('#zoomOut').onclick=()=>{zoom=Math.max(70,zoom-10);$('#vnScreen').style.transform=`scale(${zoom/100})`;$('#zoomLabel').textContent=`${zoom}%`};$('#fullscreenBtn').onclick=()=>document.body.classList.toggle('focus-preview');
document.addEventListener('keydown',e=>{if(e.code==='Space'&&!['TEXTAREA','INPUT','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();if(!playing)setMode(true);else if(!selected().choices?.length)advance()}if(e.key==='Escape'){document.body.classList.remove('focus-preview');closeModal()}});
function modal(content){$('#modalContent').innerHTML=content;$('#modalBackdrop').classList.add('open')}function closeModal(){$('#modalBackdrop').classList.remove('open')}$('#modalClose').onclick=closeModal;$('#modalBackdrop').onclick=e=>{if(e.target.id==='modalBackdrop')closeModal()};
$('#exportBtn').onclick=()=>{const json=JSON.stringify(project,null,2);modal(`<h2>Export your story</h2><p>Your complete visual novel project as a portable JSON file. Keep building in Fable or share the source with a friend.</p><textarea id="exportText" readonly></textarea><button class="button button-dark" id="downloadJson">↓ &nbsp; Download .json</button> <button class="button button-outline" id="copyJson">Copy JSON</button><button class="button button-outline" id="importJsonBtn">Import project</button><input id="importFile" type="file" accept="application/json,.json" hidden>`);$('#exportText').value=json;$('#downloadJson').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([json],{type:'application/json'}));a.download=(project.title||'story').toLowerCase().replace(/[^a-z0-9]+/g,'-')+'.json';a.click();URL.revokeObjectURL(a.href);showToast('Project exported')};$('#copyJson').onclick=async()=>{try{await navigator.clipboard.writeText(json);showToast('Project JSON copied')}catch{ $('#exportText').select();document.execCommand('copy');showToast('Project JSON copied')}};$('#importJsonBtn').onclick=()=>$('#importFile').click();$('#importFile').onchange=async e=>{try{const p=JSON.parse(await e.target.files[0].text());if(!p.title||!Array.isArray(p.scenes)||!p.scenes.length)throw Error();project=p;selectedId=p.scenes[0].id||makeId();project.scenes.forEach(s=>{if(!s.id)s.id=makeId()});changed();closeModal();showToast('Project imported')}catch{showToast('That file is not a Fable project')}}};
$('#shareBtn').onclick=()=>{modal(`<h2>Share your story</h2><p>Invite a friend to read your latest draft. This private preview link is ready to copy.</p><div style="display:flex;gap:7px"><input class="text-input" id="shareLink" readonly value="fable.studio/preview/${Math.random().toString(36).slice(2,9)}"><button class="button button-dark" id="copyLink">Copy</button></div>`);$('#copyLink').onclick=async()=>{try{await navigator.clipboard.writeText($('#shareLink').value)}catch{}showToast('Preview link copied') }};
$('#settingsNav').onclick=()=>{modal(`<h2>Project settings</h2><p>Give your story a name readers will remember.</p><label class="field-label" for="titleEdit">Project title</label><input class="text-input" id="titleEdit" maxlength="42" value="${escAttr(project.title)}"><button class="button button-dark" id="saveTitle">Save changes</button>`);$('#saveTitle').onclick=()=>{project.title=$('#titleEdit').value.trim()||'Untitled story';changed();closeModal();showToast('Project settings saved')}};
$('#newProjectBtn').onclick=()=>{modal(`<h2>Start a new story</h2><p>A blank page is a wonderful place to begin. Your current project is saved in this browser.</p><label class="field-label" for="newTitle">Story title</label><input class="text-input" id="newTitle" maxlength="42" placeholder="Untitled story" value="My new story"><button class="button button-dark" id="createProject">Create project</button>`);$('#createProject').onclick=()=>{history.push(JSON.stringify(project));project={title:$('#newTitle').value.trim()||'Untitled story',scenes:[{...structuredClone(starter.scenes[0]),id:makeId(),name:'Opening scene',speaker:'Narrator',text:'Every story begins somewhere…',next:null}]};selectedId=project.scenes[0].id;changed();closeModal();showToast('Your new story is ready')}};
$('#tipButton').onclick=$('#choiceTip').onclick=()=>modal(`<h2>A little story magic</h2><p>Fable is a visual novel studio built for stories with heart. Start small, then let your world grow.</p><div class="guide-step"><b>01</b><span><strong>Set the scene.</strong> Pick a backdrop and give your scene a name.</span></div><div class="guide-step"><b>02</b><span><strong>Let them speak.</strong> Choose a speaker and write dialogue in the inspector.</span></div><div class="guide-step"><b>03</b><span><strong>Give readers a say.</strong> Add choices and connect paths in your story.</span></div><div class="guide-step"><b>04</b><span><strong>Play it back.</strong> Hit Preview and click through your story.</span></div>`);
$('#undoBtn').onclick=()=>{if(!history.length)return showToast('Nothing to undo');future.push(JSON.stringify(project));project=JSON.parse(history.pop());selectedId=project.scenes[0].id;render();persist();showToast('Change undone')};$('#redoBtn').onclick=()=>{if(!future.length)return showToast('Nothing to redo');history.push(JSON.stringify(project));project=JSON.parse(future.pop());selectedId=project.scenes[0].id;render();persist();showToast('Change restored')};
render();

